import{_ as e,o as a,c as s,ag as o}from"./chunks/framework.qXLDknWC.js";const p=JSON.parse('{"title":"Frequently Asked Questions","description":"","frontmatter":{},"headers":[],"relativePath":"faq.md","filePath":"faq.md"}'),r={name:"faq.md"};function i(n,t,l,c,d,h){return a(),s("div",null,[...t[0]||(t[0]=[o('<h1 id="frequently-asked-questions" tabindex="-1">Frequently Asked Questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently Asked Questions&quot;">​</a></h1><h2 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h2><details class="details custom-block"><summary>What is Character Vault?</summary><p>Character Vault is a browser-based tool for creating, editing, and organizing roleplay character cards. It supports the V2/V3 character card specification and runs entirely locally — no account, no cloud, no data leaves your machine. It is compatible with SillyTavern and similar tools.</p></details><details class="details custom-block"><summary>Do I need to install anything?</summary><p>No. You can use the hosted version at <strong><a href="https://spaceman2408.github.io/CharacterVault" target="_blank" rel="noreferrer">https://spaceman2408.github.io/CharacterVault</a></strong> directly in your browser. No installation required.</p><p>If you prefer to run locally or develop on the codebase, see the <a href="/CharacterVault/docs/getting-started/installation">Installation guide</a>.</p></details><details class="details custom-block"><summary>What can I do with Character Vault?</summary><p>You can:</p><ul><li><strong>Edit every field</strong> of a V2/V3 character card — description, personality, greetings, lorebook, creator notes, and extensions</li><li><strong>Use AI to help you write</strong> through Orion (a built-in chat assistant) and an AI toolbar with enhance, rephrase, shorten, fix, and other operations</li><li><strong>Save snapshots</strong> at any point and roll back to previous versions, either the entire card or individual sections</li><li><strong>Import and export</strong> PNG cards with embedded data and JSON files, compatible with SillyTavern, TavernAI, and other tools</li><li><strong>Stay in control</strong> with local IndexedDB storage, dark and light themes</li></ul></details><hr><h2 id="ai-features" tabindex="-1">AI Features <a class="header-anchor" href="#ai-features" aria-label="Permalink to &quot;AI Features&quot;">​</a></h2><details class="details custom-block"><summary>How do I enable AI features?</summary><p>To use the AI toolbar or Orion assistant, you must configure an AI provider:</p><ol><li>Open a character in the workspace</li><li>Click <strong>Settings</strong> in the workspace header</li><li>Go to the <strong>AI Config</strong> tab</li><li>Enter your API Base URL, API Key, and select a model</li><li>Click <strong>Save Settings</strong></li></ol><p>For step-by-step instructions, see <a href="/CharacterVault/docs/configuration/ai-setup">AI Setup</a>.</p></details><details class="details custom-block"><summary>Which AI providers can I use?</summary><p>Character Vault works with any OpenAI-compatible endpoint. Presets are available for:</p><ul><li><strong>Nano-GPT</strong> — hosted endpoint with provider selection</li><li><strong>OpenRouter</strong> — multi-model gateway</li><li><strong>LM Studio / localhost</strong> — local inference</li><li><strong>Custom URL</strong> — any compatible endpoint</li></ul><p>Each preset saves your API key and model selection separately, so switching between providers restores your saved credentials.</p></details><details class="details custom-block"><summary>What does the AI toolbar do?</summary><p>The AI toolbar sits at the top of every text editor and offers several operations:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Operation</th><th style="text-align:left;">Function</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Enhance</strong></td><td style="text-align:left;">Elaborate on selected text with more detail</td></tr><tr><td style="text-align:left;"><strong>Rephrase</strong></td><td style="text-align:left;">Rewrite while preserving meaning</td></tr><tr><td style="text-align:left;"><strong>Custom</strong></td><td style="text-align:left;">Type your own instruction for the AI</td></tr><tr><td style="text-align:left;"><strong>Shorten</strong></td><td style="text-align:left;">Condense the selection</td></tr><tr><td style="text-align:left;"><strong>Lengthen</strong></td><td style="text-align:left;">Extend with additional content</td></tr><tr><td style="text-align:left;"><strong>Vivid</strong></td><td style="text-align:left;">Apply descriptive language</td></tr><tr><td style="text-align:left;"><strong>Emotion</strong></td><td style="text-align:left;">Enhance emotional expression</td></tr><tr><td style="text-align:left;"><strong>Fix</strong></td><td style="text-align:left;">Grammar and clarity improvements</td></tr></tbody></table><p>See <a href="/CharacterVault/docs/features/editor#ai-toolbar">Text Editor → AI Toolbar</a> for details.</p></details><details class="details custom-block"><summary>What is Orion?</summary><p>Orion is a built-in AI assistant that helps you brainstorm, write, and refine character content. You select which character sections Orion can see as context, then chat with it directly.</p><p>To use Orion:</p><ol><li>Open the <strong>AI Context</strong> panel and select which sections the AI can see</li><li>Open the <strong>Ask AI</strong> panel and type your question</li><li>Orion responds using the selected context</li></ol><p>Orion uses your configured AI provider and understands Character Vault&#39;s features and the V2/V3 specification. See <a href="/CharacterVault/docs/features/ai-assistant">AI Assistant — Orion</a>.</p></details><details class="details custom-block"><summary>Is my API key secure?</summary><p>Your API key is stored locally in your browser&#39;s storage. It is not sent to Character Vault&#39;s servers, but be aware that:</p><ul><li>Malicious browser extensions could potentially access it</li><li>Anyone with physical access to your unlocked computer could access it</li></ul><p>You can clear your AI settings at any time from the AI Config tab by clicking <strong>Clear AI Settings</strong>. See <a href="/CharacterVault/docs/configuration/ai-setup#security-notice">AI Setup → Security Notice</a>.</p></details><hr><h2 id="import-export" tabindex="-1">Import &amp; Export <a class="header-anchor" href="#import-export" aria-label="Permalink to &quot;Import &amp; Export&quot;">​</a></h2><details class="details custom-block"><summary>What file formats can I import?</summary><p>Character Vault accepts:</p><ul><li><strong>PNG images</strong> — character cards with embedded metadata (from SillyTavern, TavernAI, etc.)</li><li><strong>JSON files</strong> — flat V2, wrapped V2/V3, or CharacterVault&#39;s own export format</li></ul><p>For PNG files, the data is stored in a special metadata chunk inside the image. CharacterVault reads this chunk, parses the JSON, and creates a new character with the image as its avatar.</p></details><details class="details custom-block"><summary>How do I export a character?</summary><p>Open a character and click <strong>Export</strong> in the toolbar. You have two options:</p><ul><li><strong>PNG</strong> — embeds all data as V3 specification in the image file. Most versatile — works with SillyTavern, CharacterVault, and other compatible apps.</li><li><strong>JSON</strong> — exports using V3 specification. Includes name, description, personality, scenario, greetings, lorebook, creator information, tags, and notes (but not the character image).</li></ul><p>See <a href="/CharacterVault/docs/features/import-export">Import &amp; Export</a> for details.</p></details><details class="details custom-block"><summary>Can I import directly from SillyTavern?</summary><p>Yes, there are several ways:</p><p><strong>Option 1: SillyTavern CharacterVault Export Extension</strong></p><p>A browser extension that adds &quot;Export to CharacterVault&quot; to SillyTavern&#39;s export menu. When you use it, the extension copies the character to your clipboard in a format CharacterVault understands — no need to save files manually.</p><p><strong>Option 2: Clipboard Import</strong></p><ol><li>In SillyTavern, copy a character to the clipboard</li><li>Open Character Vault and navigate to the <strong>Import</strong> page (or use the <code>/import</code> route directly)</li><li>Paste the character data to import it</li></ol><p>See <a href="/CharacterVault/docs/getting-started/installation#sillytavern-integration">Installation → SillyTavern Integration</a>.</p></details><hr><h2 id="snapshots-history" tabindex="-1">Snapshots &amp; History <a class="header-anchor" href="#snapshots-history" aria-label="Permalink to &quot;Snapshots &amp; History&quot;">​</a></h2><details class="details custom-block"><summary>How do snapshots work?</summary><p>Every character card maintains a local snapshot history. When you open a character, a baseline snapshot is created automatically. You can also create manual snapshots at any time to save your progress.</p><p>To access snapshots:</p><ol><li>Open a character in the workspace</li><li>Click <strong>Snapshots</strong> in the workspace header</li><li>Browse the timeline and select a snapshot to compare with your current draft</li></ol><p>You can restore the entire card or restore individual sections. Each restore automatically creates a rollback snapshot so you can undo if needed. See <a href="/CharacterVault/docs/features/snapshots-history">Snapshots &amp; Rollback</a>.</p></details><details class="details custom-block"><summary>What types of snapshots exist?</summary><table tabindex="0"><thead><tr><th style="text-align:left;">Badge</th><th style="text-align:left;">When It&#39;s Created</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Opened card</strong></td><td style="text-align:left;">Automatically the first time you open a character card. Only one baseline exists per character; it is protected from deletion.</td></tr><tr><td style="text-align:left;"><strong>Manual save point</strong></td><td style="text-align:left;">When you click <strong>Save snapshot</strong> in the Snapshots modal.</td></tr><tr><td style="text-align:left;"><strong>Post-restore save point</strong></td><td style="text-align:left;">Automatically after a restore (full card or section) completes. This records the state right after the rollback is applied.</td></tr></tbody></table><p>You may occasionally see a <strong>&quot;Legacy auto save point&quot;</strong> badge on older snapshots. These were created automatically by an earlier version of the app. No new auto snapshots are created in the current version.</p></details><details class="details custom-block"><summary>How many snapshots can I keep?</summary><p>Each character is limited to 10 saved snapshots (not including the baseline &quot;Opened card&quot; snapshot). When the limit is exceeded, the oldest ones are removed automatically.</p><p>Storage notes:</p><ul><li>If nothing has changed since the latest snapshot, a new one won&#39;t be created</li><li>Snapshot images are memory-optimized — they only store image data when the image actually changed</li><li>Snapshots are local; clearing browser data removes all snapshot history</li></ul></details><hr><h2 id="storage-data" tabindex="-1">Storage &amp; Data <a class="header-anchor" href="#storage-data" aria-label="Permalink to &quot;Storage &amp; Data&quot;">​</a></h2><details class="details custom-block"><summary>Where is my data stored?</summary><p>All character data is stored locally in your browser using IndexedDB. No data is sent to external servers. This includes character cards and images, snapshot history, AI configuration and settings, and UI preferences.</p></details><details class="details custom-block"><summary>What happens if I clear my browser data?</summary><div class="warning custom-block"><p class="custom-block-title">What happens when you clear your browser data:</p><p>Your cache, local storage, IndexedDB will remove all your characters, settings, and snapshot history.</p><div class="danger custom-block"><p class="custom-block-title">BACKUP YOUR CHARACTERS</p><p>For important characters, export a PNG backup before clearing browser data. See <a href="/CharacterVault/docs/features/import-export">Import &amp; Export</a>.</p></div></div></details><details class="details custom-block"><summary>Can I use Character Vault offline?</summary><p>The app works offline. You can create, edit, organize, import, and export characters without an internet connection.</p><p>AI features (Orion assistant and AI toolbar) require an internet connection to reach your configured API endpoint.</p></details><hr><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><details class="details custom-block"><summary>The AI toolbar buttons are disabled</summary><p>This typically means one of two things:</p><ul><li><strong>No AI provider configured</strong> — See <a href="/CharacterVault/docs/configuration/ai-setup">AI Setup</a> to configure a provider.</li><li><strong>Selection too long</strong> — The selected text exceeds the AI&#39;s context window. Either select less text or increase the Context Length setting in Settings → Sampler tab.</li></ul></details><details class="details custom-block"><summary>My API requests are failing</summary><p>Common causes include:</p><ul><li><strong>Missing /v1 in URL</strong> — If your base URL doesn&#39;t end in <code>/v1</code>, the error message will suggest adding it. This is a common configuration mistake with OpenAI-compatible endpoints.</li><li><strong>Invalid API key</strong> — Verify your key is correct and hasn&#39;t expired. Check your provider&#39;s dashboard for status.</li><li><strong>Wrong model</strong> — Ensure the model ID matches what your provider offers. Use the <strong>Fetch</strong> button in Settings to see available models.</li><li><strong>Context length too small</strong> — If you&#39;re sending too much content, increase the Context Length in Settings → Sampler tab.</li></ul><p>See <a href="/CharacterVault/docs/configuration/ai-setup#troubleshooting-context-warnings">AI Setup → Troubleshooting</a> for more.</p></details><details class="details custom-block"><summary>The context window is too small warning</summary><p>This appears when your content exceeds the configured context length. Solutions:</p><ul><li>Select less text for AI operations</li><li>Increase <strong>Context Length</strong> in Settings → Sampler tab</li><li>Decrease <strong>Max Tokens</strong> to leave more room for input</li></ul><p>The system reserves a 100-token safety margin automatically.</p></details><details class="details custom-block"><summary>Can I customize the AI prompts?</summary><p>Yes, all eight toolbar operation prompts are customizable:</p><ol><li>Open <strong>Settings</strong> in the workspace header</li><li>Go to the <strong>Prompts</strong> tab</li><li>Edit the prompt template for any operation</li></ol><p>Each prompt must include <code>${text}</code> as a placeholder (the selected or full editor content). The Custom operation also requires <code>${instruction}</code>. See <a href="/CharacterVault/docs/features/editor#customizing-ai-prompts">Text Editor → Customizing AI Prompts</a>.</p></details><details class="details custom-block"><summary>How do I report a bug or request a feature?</summary><p>Visit the <a href="https://github.com/spaceman2408/CharacterVault" target="_blank" rel="noreferrer">Character Vault GitHub repository</a> to open an issue.</p></details>',34)])])}const m=e(r,[["render",i]]);export{p as __pageData,m as default};
